// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): no Cmp token layer, reads no tokens at all.
//
// Shows its children only from, or only below, a step of the breakpoint ladder, so a page can
// place one control in two spots by width (a docked action on a phone, the same action inline on
// a wide screen) and exactly one copy is ever in use. It renders no content and adds no box:
// shown, its wrapper is `display: contents`, so its children take part in the parent's flex or
// grid as if the wrapper were absent; hidden, it is `display: none`, which also takes the
// children out of the accessibility tree, the right outcome when the other copy is the live one.
//
// Prop words: `from` / `below` read as the sentence "show from large", "show below large", and
// take the Sys breakpoint step names (`medium` 768 · `large` 1024) verbatim, the same values as
// AppShell's `breakpoint`. `small` is not offered: it is the base, so "from small" is always and
// "below small" is never.
import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import "./Show.css";

type Step = "medium" | "large";

interface ShowChildrenProps {
  children?: ReactNode;
  /** Show the children from this step up (min-width, mobile-first); hidden below it. */
  from?: Step;
  /**
   * Hide the children from this step up; shown below it. Given with `from`, the children show
   * only in the band between the two (`from="medium" below="large"`).
   */
  below?: Step;
}

interface ShowHostProps extends Omit<HTMLAttributes<HTMLDivElement>, "className" | "role" | "children"> {
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export type ShowProps = ShowChildrenProps &
  // At least one of the two is required.
  ({ from: Step } | { below: Step }) &
  ShowHostProps;

export function Show({ from, below, className, ...props }: ShowProps) {
  // `role` is omitted from the props on purpose: `display: contents` drops the wrapper's own box,
  // and some engines drop a role along with it. A role-less div exposes nothing, so nothing is lost.
  return (
    <div
      {...props}
      data-from={from}
      data-below={below}
      className={className ? `sd-show ${className}` : "sd-show"}
    />
  );
}

/* Show.css — .sd-show
   Layout primitive: shows its children from, or below, a breakpoint step. Carve-out 5 — reads no
   tokens. Shown is `display: contents` (no box of its own, children join the parent's layout);
   hidden is `display: none`. Widths are the Sys breakpoint ladder (tokens/sys/breakpoint.json),
   hardcoded because @media cannot read var(). Mobile-first: the `below` rules sit after the
   `from` rules at each width, so a band (`from` + `below`) hides once its upper step is reached.
   Single class, no descendant combinators. */
.sd-show {
  display: contents;
}

.sd-show[data-from] {
  display: none;
}

@media (min-width: 768px) {
  .sd-show[data-from="medium"] {
    display: contents;
  }

  .sd-show[data-below="medium"] {
    display: none;
  }
}

@media (min-width: 1024px) {
  .sd-show[data-from="large"] {
    display: contents;
  }

  .sd-show[data-below="large"] {
    display: none;
  }
}
